int cmp_int(const void * p, const void * q) {
    int a =  * (const int * )p, b =  * (const int * )q;
    return(a > b) - (a < b);
}
int main(void) {
    int n, a[1000];
    scanf("%d",  & n);
    for (int i = 0; i < n; i++)scanf("%d",  & a[i]);
    qsort(a, (size_t)n, sizeof * a, cmp_int);
    for (int i = 0; i < n / 2; i++) {
        int t = a[i];
        a[i] = a[n - 1 - i];
        a[n - 1 - i] = t;
    }
    if (n == 0)puts("EMPTY");
    for (int i = 0; i < n; i++)printf("%d%c", a[i], i + 1 == n ? '\n': ' ');
    return 0;
}

