int main(void) {
    char a[102], b[102];
    if (!fgets(a, sizeof a, stdin))a[0] = 0;
    if (!fgets(b, sizeof b, stdin))b[0] = 0;
    a[strcspn(a, "\n")] = 0;
    b[strcspn(b, "\n")] = 0;
    int n = (int)strlen(a), m = (int)strlen(b), dp[101][101];
    for (int i = 0; i <= n; i++)dp[i][0] = i;
    for (int j = 0; j <= m; j++)dp[0][j] = j;
    for (int i = 1; i <= n; i++)for (int j = 1; j <= m; j++) {
        int best = dp[i - 1][j] + 1;
        if (dp[i][j - 1] + 1 < best)best = dp[i][j - 1] + 1;
        if (dp[i - 1][j - 1] + (a[i - 1] != b[j - 1]) < best)best = dp[i - 1][j - 1] + (a[i - 1] != b[j - 1]);
        dp[i][j] = best;
    }
    printf("%d\n", dp[n][m]);
    return 0;
}

